-- Scope: tagged fictional records only; preserve IDs, monetary values and accepted offers.
CREATE TEMP TABLE identity_labels(ordinal integer,old_name text,first_name text,last_name text,company_name text,email text) ON COMMIT DROP;
CREATE TEMP TABLE identity_customers ON COMMIT DROP AS SELECT c.id,l.* FROM customers c JOIN sample_data_records r ON r.entity_id=c.id AND r.entity='customer' AND r.batch_id='ux01-customers-v1' JOIN identity_labels l ON c.name=l.old_name;
UPDATE customers c SET name=CASE WHEN m.company_name='' THEN m.first_name||' '||m.last_name ELSE m.company_name END FROM identity_customers m WHERE c.id=m.id;
UPDATE customer_profiles p SET first_name=CASE WHEN m.company_name='' THEN m.first_name ELSE '' END,last_name=CASE WHEN m.company_name='' THEN m.last_name ELSE '' END,company_name=m.company_name,revision=revision+1,updated_at=now() FROM identity_customers m WHERE p.customer_id=m.id AND ((p.first_name='CLIENTE' AND p.last_name LIKE 'PRUEBA %') OR p.company_name=m.old_name);
UPDATE customer_contacts c SET first_name=m.first_name,last_name=m.last_name,email=CASE WHEN c.email ~ '^ux01-cliente-[0-9]+@example.invalid$' THEN m.email ELSE c.email END FROM identity_customers m WHERE c.customer_id=m.id AND upper(c.first_name)='CONTACTO' AND upper(c.last_name)='PRUEBA';
CREATE TEMP TABLE identity_sites(id text,old_name text,new_name text,old_code text,new_code text) ON COMMIT DROP;

UPDATE properties p SET name=m.new_name,code=m.new_code,revision=revision+1,updated_at=now() FROM identity_sites m WHERE p.id=m.id;
UPDATE properties p SET contact_name=m.first_name||' '||m.last_name FROM identity_customers m JOIN sample_data_records r ON r.entity='property' AND r.batch_id='ux01-customers-v1' WHERE p.id=r.entity_id AND p.customer_id=m.id AND upper(p.contact_name)='CONTACTO PRUEBA';
UPDATE property_zones z SET name='Jardín frontal',revision=revision+1 WHERE name='Césped de ejemplo' AND EXISTS(SELECT 1 FROM sample_data_records r WHERE r.entity='property' AND r.entity_id=z.property_id AND r.batch_id='ux01-customers-v1');
CREATE TEMP TABLE identity_staff(first_name text,last_name text,email text) ON COMMIT DROP;
CREATE TEMP TABLE identity_employees ON COMMIT DROP AS SELECT e.id,e.first_name||' '||e.last_name old_name,m.first_name||' '||m.last_name new_name,m.last_name,m.email FROM employees e JOIN identity_staff m ON e.first_name=m.first_name JOIN sample_scenario_records r ON r.entity='employee' AND r.entity_id=e.id AND r.batch_id='ops01-scenario-v1' WHERE e.last_name='EJEMPLO';
UPDATE employees e SET last_name=m.last_name,email=CASE WHEN e.email ~ '^equipo-[0-9]+@example.invalid$' THEN m.email ELSE e.email END,revision=revision+1 FROM identity_employees m WHERE e.id=m.id;
UPDATE visit_personnel p SET name_snapshot=m.new_name FROM identity_employees m WHERE p.employee_id=m.id AND p.name_snapshot=m.old_name AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='visit' AND r.entity_id=p.visit_id AND r.batch_id='ops01-scenario-v1');
UPDATE crews x SET name=replace(replace(name,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (name LIKE 'PRUEBA · %' OR name LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='crew' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');
UPDATE contracts x SET service=replace(replace(service,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (service LIKE 'PRUEBA · %' OR service LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='contract' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');
UPDATE visits x SET title=replace(replace(title,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (title LIKE 'PRUEBA · %' OR title LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='visit' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');
UPDATE property_zones x SET name=replace(replace(name,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (name LIKE 'PRUEBA · %' OR name LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='zone' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');
UPDATE property_elements x SET name=replace(replace(name,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (name LIKE 'PRUEBA · %' OR name LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='element' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');
UPDATE production_rates x SET name=replace(replace(name,'PRUEBA · ',''),' · PRUEBA',''),revision=revision+1 WHERE (name LIKE 'PRUEBA · %' OR name LIKE '% · PRUEBA') AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='rate' AND r.entity_id=x.id AND r.batch_id='ops01-scenario-v1');

UPDATE visits v SET title=replace(v.title,m.old_name,m.new_name) FROM identity_sites m,contracts c WHERE v.contract_id=c.id AND c.property_id=m.id AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='visit' AND r.entity_id=v.id AND r.batch_id='ops01-scenario-v1');
UPDATE catalog_options c SET label=replace(c.label,' · PRUEBA',''),revision=revision+1 WHERE c.label LIKE '% · PRUEBA' AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='catalog' AND r.entity_id=c.category||':'||c.key AND r.batch_id='ops01-scenario-v1');
UPDATE visit_tasks x SET description=substr(description,10) WHERE description LIKE 'PRUEBA · %' AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='visit' AND r.entity_id=x.visit_id AND r.batch_id='ops01-scenario-v1');
UPDATE visit_cost_lines x SET description=substr(description,10) WHERE description LIKE 'PRUEBA · %' AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='visit' AND r.entity_id=x.visit_id AND r.batch_id='ops01-scenario-v1');
UPDATE invoice_lines x SET description=substr(description,10) WHERE description LIKE 'PRUEBA · %' AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='invoice' AND r.entity_id=x.invoice_id AND r.batch_id='ops01-scenario-v1');

UPDATE invoices i SET notes=replace(notes,'DOCUMENTO SINTÉTICO DE PRUEBA.','DOCUMENTO DE EVALUACIÓN.') WHERE notes LIKE 'DOCUMENTO SINTÉTICO DE PRUEBA.%' AND EXISTS(SELECT 1 FROM sample_scenario_records r WHERE r.entity='invoice' AND r.entity_id=i.id AND r.batch_id='ops01-scenario-v1');
-- New draft revisions preserve immutable originals and all calculations.
CREATE TEMP TABLE identity_estimates ON COMMIT DROP AS SELECT e.id,e.revision,replace(e.title,'PRUEBA · ','') title,
jsonb_set(jsonb_set(jsonb_set(replace(replace(replace(replace(r.snapshot::text,'PRUEBA · ',''),' · PRUEBA',''),'Césped de ejemplo','Jardín frontal'),'Datos de prueba.','Datos de evaluación.')::jsonb,'{input,title}',to_jsonb(replace(e.title,'PRUEBA · ',''))),'{property,name}',to_jsonb(p.name)),'{property,code}',to_jsonb(p.code)) snapshot
FROM estimate_drafts e JOIN estimate_revisions r ON r.estimate_id=e.id AND r.revision=e.revision JOIN properties p ON p.id=e.property_id
WHERE e.title LIKE 'PRUEBA · %' AND e.revision=1 AND EXISTS(SELECT 1 FROM sample_scenario_records s WHERE s.entity='estimate' AND s.entity_id=e.id AND s.batch_id='ops01-scenario-v1') AND NOT EXISTS(SELECT 1 FROM estimate_offers o WHERE o.estimate_id=e.id);
UPDATE estimate_drafts e SET title=m.title,revision=m.revision+1,updated_at=now() FROM identity_estimates m WHERE e.id=m.id;
UPDATE sample_data_batches SET manifest=manifest||'{"identity_version":2}'::jsonb WHERE id IN ('ux01-customers-v1','ops01-scenario-v1');
-- Exact legacy bootstrap signatures only; user-renamed records are excluded.
UPDATE crews SET name='Cuadrilla Alameda',revision=revision+1 WHERE name='Cuadrilla Norte · Demo' AND workers=2 AND hourly_cents=2400 AND NOT EXISTS(SELECT 1 FROM crew_employees e WHERE e.crew_id=crews.id);
UPDATE properties SET name='Jardín Alameda',revision=revision+1 WHERE name='Jardín Alameda · Demo' AND lawn_sqft=8400 AND address='Dirección ficticia';
UPDATE customers SET name='CAMILO SANTANA' WHERE name='Cliente de demostración' AND NOT EXISTS(SELECT 1 FROM customer_profiles p WHERE p.customer_id=customers.id);
